package org.cc104.solutions;

/**
 * <h2>Problem 1: Count Target Occurrences</h2>
 *
 * <h3>Problem Statement</h3>
 * <br/>
 * Given a sorted array of integers `nums` and an integer `target`, return the count of how many times `target` appears in `nums`.
 * <br/>
 * Implement two versions of the solution:
 * <br/>
 * 1. Using <b>linear search</b> (O(n) time complexity) <br/>
 * 2. Using <b>binary search</b> (O(log n) time complexity)
 */
public int countOccurrencesLinear(int[] nums, int target) {
    int count = 0;

    for (int num : nums) {
        if (num == target) {
            count++;
        }
    }

    return count;
}

public int countOccurrencesBinary(int[] nums, int target) {
    int first = findFirst(nums, target);

    if (first == -1) {
        return 0;
    }

    int last = findLast(nums, target);

    return last - first + 1;
}

private int findFirst(int[] nums, int target) {
    int low = 0;
    int high = nums.length - 1;
    int result = -1;

    while (low <= high) {
        int mid = (low + high) / 2;

        if (nums[mid] == target) {
            result = mid;
            high = mid - 1;
        } else if (nums[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return result;
}

private int findLast(int[] nums, int target) {
    int low = 0;
    int high = nums.length - 1;
    int result = -1;

    while (low <= high) {
        int mid = (low + high) / 2;

        if (nums[mid] == target) {
            result = mid;
            low = mid + 1;
        } else if (nums[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return result;
}
